using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Printing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace VinsPDF {
internal sealed class ToolDialog : DarkWindow {
 public readonly ListBox Items=new ListBox{Dock=DockStyle.Fill,BackColor=Color.FromArgb(24,27,30),ForeColor=Color.Gainsboro,BorderStyle=BorderStyle.None};
 public readonly TextBox Input=new TextBox{Dock=DockStyle.Top,BackColor=Color.FromArgb(24,27,30),ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle};
 readonly FlowLayoutPanel actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=72,Padding=new Padding(6)};
 public ToolDialog(string title,string instructions){Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);Text=title;Size=new Size(540,430);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",9);var note=new Label{Text=instructions,Dock=DockStyle.Top,Height=65,Padding=new Padding(10),ForeColor=Color.Silver};Controls.Add(Items);Controls.Add(Input);Controls.Add(note);Controls.Add(actions);InstallTitle();HideMinMax();Add("Cancel",delegate{DialogResult=DialogResult.Cancel;});}
 public void Add(string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=27,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(28,32,36),ForeColor=Color.White};b.Click+=delegate{action();};actions.Controls.Add(b);}
 public void MoveItem(int delta){int i=Items.SelectedIndex,j=i+delta;if(i<0||j<0||j>=Items.Items.Count)return;object item=Items.Items[i];Items.Items.RemoveAt(i);Items.Items.Insert(j,item);Items.SelectedIndex=j;}
}
internal sealed class PageChoice {public int Index,Rotation;public override string ToString(){return "Page "+(Index+1)+(Rotation!=0?" · rotate "+Rotation*90+"°":"");}}
internal sealed partial class MainForm {
 internal void RunTool(string tool){if(editBusy||!FinishInline())return;if(tool!="combine"&&sizes==null)return;Form owner=TopLevelControl as Form??this;
 if(tool=="print"){var job=new PrintDocument{PrintController=new StandardPrintController()};using(var dialog=new PrintDialog{Document=job,UseEXDialog=true,AllowSomePages=true}){job.PrinterSettings.MinimumPage=1;job.PrinterSettings.MaximumPage=sizes.Length;job.PrinterSettings.FromPage=1;job.PrinterSettings.ToPage=sizes.Length;if(dialog.ShowDialog(owner)!=DialogResult.OK){job.Dispose();return;}}int first=job.PrinterSettings.PrintRange==PrintRange.SomePages?job.PrinterSettings.FromPage-1:0,last=job.PrinterSettings.PrintRange==PrintRange.SomePages?job.PrinterSettings.ToPage-1:sizes.Length-1;ToolWork("Printing",delegate(PdfEngine e){try{e.Print(job,first,last);}finally{job.Dispose();}},null);return;}
 if(tool=="export"){ExportDocument();return;}
 if(tool=="organise"){OrganisePages();return;}
 if(tool=="extract"){using(var d=new ToolDialog("Extract pages","Enter page numbers/ranges in the desired order, e.g. 1,3,5-8. A new PDF is created; your open document stays unchanged.")){d.Items.Visible=false;d.Height=230;d.Input.Text=(pageIndex+1).ToString();d.Add("Extract…",delegate{try{PdfEngine.PageRange(d.Input.Text,sizes.Length);d.DialogResult=DialogResult.OK;}catch(Exception ex){DarkMessage.Show(d,ex.Message);}});if(d.ShowDialog(owner)!=DialogResult.OK)return;int[] order=PdfEngine.PageRange(d.Input.Text,sizes.Length);string path=ExportPath("Extract pages");if(path!=null)ToolWork("Extracting",delegate(PdfEngine e){e.ExportPages(path,order);},path);}return;}
 using(var d=new ToolDialog(tool=="combine"?"Combine files":"Organise pages",tool=="combine"?"Add PDFs and arrange their order. The combined document is saved as a new PDF.":"Reorder, remove or rotate pages. Save the result as a new PDF. Bookmarks, forms and document-level layers may not transfer to a new document.")){d.Input.Visible=false;if(tool=="combine"){d.Add("Add files…",delegate{using(var open=new OpenFileDialog{Filter="PDF files|*.pdf",Multiselect=true})if(open.ShowDialog(d)==DialogResult.OK)d.Items.Items.AddRange(open.FileNames);});}else{for(int i=0;i<sizes.Length;i++)d.Items.Items.Add(new PageChoice{Index=i});d.Add("Rotate 90°",delegate{int i=d.Items.SelectedIndex;if(i<0)return;var item=(PageChoice)d.Items.Items[i];item.Rotation=(item.Rotation+1)%4;d.Items.Items[i]=item;});}
 d.Add("Up",delegate{d.MoveItem(-1);});d.Add("Down",delegate{d.MoveItem(1);});d.Add("Remove",delegate{int i=d.Items.SelectedIndex;if(i>=0)d.Items.Items.RemoveAt(i);});d.Add("Save PDF…",delegate{if(d.Items.Items.Count>0)d.DialogResult=DialogResult.OK;});if(d.ShowDialog(owner)!=DialogResult.OK)return;string path=ExportPath(tool=="combine"?"Combine files":"Organise pages");if(path==null)return;if(tool=="combine"){string[] files=d.Items.Items.Cast<string>().ToArray();if(files.Any(f=>string.Equals(Path.GetFullPath(f),Path.GetFullPath(path),StringComparison.OrdinalIgnoreCase))){DarkMessage.Show(owner,"Choose a destination different from the source files.");return;}ToolWork("Combining",delegate(PdfEngine e){e.Combine(path,files);},path);}else{var pages=d.Items.Items.Cast<PageChoice>().ToArray();ToolWork("Organising",delegate(PdfEngine e){e.ExportPages(path,pages.Select(i=>i.Index).ToArray(),pages.Select(i=>i.Rotation).ToArray());},path);}}
 }
 string ExportPath(string title){using(var d=new SaveFileDialog{Title=title,Filter="PDF document|*.pdf",DefaultExt="pdf",AddExtension=true,OverwritePrompt=true,FileName= currentPath==null?"Combined.pdf":Path.GetFileNameWithoutExtension(currentPath)+"-export.pdf"}){if(d.ShowDialog(TopLevelControl as Form??this)!=DialogResult.OK)return null;if(currentPath!=null&&string.Equals(Path.GetFullPath(d.FileName),Path.GetFullPath(currentPath),StringComparison.OrdinalIgnoreCase)){DarkMessage.Show(this,"Choose a different name to keep the open source document intact.");return null;}return d.FileName;}}
 void ToolWork(string label,Action<PdfEngine> action,string output,bool openOutput=true){editBusy=true;viewVersion++;UpdateEditorTools();status.Text=label+"…";worker.Command(delegate(PdfEngine e){try{action(e);Post(delegate{editBusy=false;UpdateEditorTools();status.Text=output==null?"Sent to printer":openOutput?"Saved · "+output:"Images exported · "+Path.GetDirectoryName(output);RequestRender();if(output!=null&&openOutput&&OpenInTab!=null)OpenInTab(output);},null);}catch(Exception ex){string message=ex.Message;Post(delegate{editBusy=false;UpdateEditorTools();DarkMessage.Show(TopLevelControl as Form??this,message,label+" failed");RequestRender();},null);}});}
}
}
